import { useMemo } from 'react';
import { Ellipsis } from '@signozhq/icons';
import { Button } from '@signozhq/ui/button';
import { Dropdown, type DropdownItemType } from '@signozhq/ui/dropdown';
import { type LlmpricingruletypesLLMPricingRuleDTO } from 'api/generated/services/sigNoz.schemas';

interface ModelCostActionsMenuProps {
	rule: LlmpricingruletypesLLMPricingRuleDTO;
	canManage: boolean;
	onEdit: (rule: LlmpricingruletypesLLMPricingRuleDTO) => void;
	onDelete: (rule: LlmpricingruletypesLLMPricingRuleDTO) => void;
}

// Per-row kebab menu for the model-costs table. Only manage users get actions
// (Edit + Delete); view-only users have nothing to act on, so the cell stays
// empty rather than showing a single-item menu.
function ModelCostActionsMenu({
	rule,
	canManage,
	onEdit,
	onDelete,
}: ModelCostActionsMenuProps): JSX.Element | null {
	const menuItems = useMemo<DropdownItemType[]>(
		() => [
			{
				type: 'item',
				value: 'edit',
				label: 'Edit',
				onClick: (): void => onEdit(rule),
			},
			{
				type: 'item',
				value: 'delete',
				label: 'Delete',
				danger: true,
				onClick: (): void => onDelete(rule),
			},
		],
		[onEdit, onDelete, rule],
	);

	if (!canManage) {
		return null;
	}

	return (
		<Dropdown items={menuItems} nativeButton align="end" side="bottom">
			<Button
				variant="ghost"
				color="secondary"
				size="sm"
				icon
				aria-label="Model cost actions"
				testId={`model-cost-actions-${rule.id}`}
			>
				<Ellipsis size={16} />
			</Button>
		</Dropdown>
	);
}

export default ModelCostActionsMenu;

/**
 * AI-owned. Generated and maintained by the `signoz-page-story` skill.
 * Do not hand-edit: regenerate instead.
 */

import ROUTES from 'constants/routes';
import { rest } from 'msw';

import { choiceControl, countControl } from '@/storybook/controls/controls';
import { defineStoryMocks } from '@/storybook/controls/defineStoryMocks';

import {
	PRICING_RULE_MAX,
	pricingRulesResponse,
	RULE_DELETES,
	RULE_SAVES,
	type RuleDelete,
	type RuleSave,
	UNPRICED_MODEL_MAX,
	unmappedModelsResponse,
} from './__story_mockdata__/modelPricing';

const RULES = 'Model pricing · rules';
const WRITES = 'Model pricing · writes';

export const modelPricingMocks = defineStoryMocks({
	controls: {
		rules: countControl('Pricing rules', {
			group: RULES,
			description:
				'Rows the model costs table has. Every fourth is a user override, which is what the source filter splits on.',
			value: 10,
			max: PRICING_RULE_MAX,
		}),
		unpricedModels: countControl('Unpriced models', {
			group: RULES,
			description:
				'Models seen in traces that no rule matches: the count on the tab badge, and the rows behind it.',
			value: 3,
			max: UNPRICED_MODEL_MAX,
		}),
		ruleSave: choiceControl<RuleSave>('Rule save', {
			group: WRITES,
			description:
				'How the PUT behind the cost drawer\'s Save and the unpriced tab\'s "Map model" answers. `success` raises the saved or "Mapped model" toast, `loading` never answers, `error` shows the failure in the drawer or raises the error toast.',
			options: RULE_SAVES,
			value: 'success',
		}),
		ruleDelete: choiceControl<RuleDelete>('Rule delete', {
			group: WRITES,
			description:
				"How the DELETE behind the row menu's Delete answers. `success` raises the deleted toast, `loading` never answers, `error` raises the error toast.",
			options: RULE_DELETES,
			value: 'success',
		}),
	},
	handlers: (values, response) => [
		rest.put('http://localhost/api/v1/llm_pricing_rules', (_req, res, ctx) => {
			if (values.ruleSave === 'loading') {
				return res(ctx.delay('infinite'));
			}

			return values.ruleSave === 'error'
				? res(
						ctx.status(500),
						ctx.json({
							status: 'error',
							error: { code: 'internal', message: 'Could not save the pricing rule' },
						}),
					)
				: res(ctx.status(204));
		}),
		rest.delete(
			'http://localhost/api/v1/llm_pricing_rules/:id',
			(_req, res, ctx) => {
				if (values.ruleDelete === 'loading') {
					return res(ctx.delay('infinite'));
				}

				return values.ruleDelete === 'error'
					? res(
							ctx.status(500),
							ctx.json({
								status: 'error',
								error: {
									code: 'internal',
									message: 'Could not delete the pricing rule',
								},
							}),
						)
					: res(ctx.status(204));
			},
		),
		rest.get(
			'http://localhost/api/v1/llm_pricing_rules/unmapped_models',
			response.json(() => unmappedModelsResponse(values.unpricedModels)),
		),
		rest.get(
			'http://localhost/api/v1/llm_pricing_rules',
			response.json((req) => {
				const isOverride = req.url.searchParams.get('isOverride');

				return pricingRulesResponse(values.rules, {
					offset: Number(req.url.searchParams.get('offset') ?? 0),
					limit: Number(req.url.searchParams.get('limit') ?? 20),
					overridesOnly: isOverride === 'true',
				});
			}),
		),
	],
	config: () => ({ route: ROUTES.AI_OBSERVABILITY_CONFIGURATION }),
});

import {
	LlmpricingruletypesLLMPricingRuleCacheModeDTO as CacheModeDTO,
	LlmpricingruletypesLLMPricingRuleUnitDTO as UnitDTO,
	type ListLLMPricingRules200,
	type ListUnmappedLLMModels200,
} from 'api/generated/services/sigNoz.schemas';

import type { PricingRule, UnpricedModel } from '../types';

// Endpoint glob used by MSW handlers. The generated client hits a relative
// `/api/v1/llm_pricing_rules`, so the `*` prefix matches regardless of base URL.
export const LLM_PRICING_ENDPOINT = '*/api/v1/llm_pricing_rules';
export const LLM_PRICING_RULE_ENDPOINT = '*/api/v1/llm_pricing_rules/:id';
// Distinct path (extra segment), so it needs its own handler — the list glob
// above does not match it.
export const LLM_UNMAPPED_ENDPOINT =
	'*/api/v1/llm_pricing_rules/unmapped_models';

// Builds a valid pricing rule, with overrides merged shallowly. Pricing is
// replaced wholesale when provided so callers can shape cache buckets freely.
export function makePricingRule(
	overrides: Partial<PricingRule> = {},
): PricingRule {
	const { pricing, ...rest } = overrides;
	return {
		id: 'rule-1',
		enabled: true,
		isOverride: true,
		modelName: 'gpt-4o',
		modelPattern: ['gpt-4o'],
		orgId: 'org-1',
		provider: 'OpenAI',
		sourceId: 'source-1',
		unit: UnitDTO.per_million_tokens,
		createdAt: '2023-10-01T00:00:00.000Z',
		updatedAt: '2023-10-10T00:00:00.000Z',
		syncedAt: '2023-10-10T00:00:00.000Z',
		pricing: {
			input: 3,
			output: 9,
			...pricing,
		},
		...rest,
	};
}

export const mockRules: PricingRule[] = [
	makePricingRule({
		id: 'rule-openai',
		modelName: 'gpt-4o',
		provider: 'OpenAI',
		isOverride: true,
		pricing: { input: 3, output: 9 },
	}),
	makePricingRule({
		id: 'rule-anthropic',
		modelName: 'claude-3-5-sonnet',
		provider: 'Anthropic',
		isOverride: false,
		pricing: {
			input: 2,
			output: 30,
			cache: { mode: CacheModeDTO.additive, read: 3, write: 6 },
		},
	}),
];

// Unpriced models seen in traces with no matching pricing rule.
export const mockUnpricedModels: UnpricedModel[] = [
	{ modelName: 'gpt-4o-mini-2024-07-18', provider: 'openai', spanCount: 18400 },
	{
		modelName: 'claude-3-7-sonnet-20250219',
		provider: 'anthropic',
		spanCount: 9200,
	},
];

// Wraps unpriced models in the envelope the unmapped-models query reads.
export function makeUnmappedResponse(
	items: UnpricedModel[] = mockUnpricedModels,
): ListUnmappedLLMModels200 {
	return {
		status: 'success',
		data: { items },
	};
}

// Wraps items in the list response envelope the list query reads
// (`data.data.items` / `data.data.total`).
export function makeListResponse(
	items: PricingRule[],
	total = items.length,
	offset = 0,
	limit = 20,
): ListLLMPricingRules200 {
	return {
		status: 'success',
		data: {
			items,
			total,
			offset,
			limit,
		},
	};
}

/**
 * AI-owned. Generated and maintained by the `signoz-page-story` skill.
 * Do not hand-edit: regenerate instead.
 */

import type {
	ListLLMPricingRules200,
	ListUnmappedLLMModels200,
	LlmpricingruletypesLLMPricingRuleDTO,
} from 'api/generated/services/sigNoz.schemas';
import {
	LlmpricingruletypesLLMPricingRuleCacheModeDTO,
	LlmpricingruletypesLLMPricingRuleUnitDTO,
} from 'api/generated/services/sigNoz.schemas';

const ORG_ID = 'org-signoz';

interface ModelSeed {
	provider: string;
	modelName: string;
	input: number;
	output: number;
}

/** Prices are dollars per million tokens, which is the only unit the rules have. */
const CATALOGUE: ModelSeed[] = [
	{ provider: 'openai', modelName: 'gpt-4o', input: 2.5, output: 10 },
	{ provider: 'openai', modelName: 'gpt-4o-mini', input: 0.15, output: 0.6 },
	{ provider: 'openai', modelName: 'o3', input: 2, output: 8 },
	{ provider: 'anthropic', modelName: 'claude-sonnet-4', input: 3, output: 15 },
	{ provider: 'anthropic', modelName: 'claude-haiku-4', input: 0.8, output: 4 },
	{ provider: 'google', modelName: 'gemini-2.5-pro', input: 1.25, output: 10 },
	{ provider: 'google', modelName: 'gemini-2.5-flash', input: 0.3, output: 2.5 },
	{ provider: 'meta', modelName: 'llama-3.1-70b', input: 0.6, output: 0.6 },
	{ provider: 'mistral', modelName: 'mistral-large', input: 2, output: 6 },
	{ provider: 'cohere', modelName: 'command-r-plus', input: 2.5, output: 10 },
];

export const PRICING_RULE_MAX = CATALOGUE.length;

/**
 * A rule the org wrote itself is an override; the rest are the catalogue SigNoz
 * ships and syncs, which is what the source filter splits the table by.
 */
const isOverride = (index: number): boolean => index % 4 === 0;

const rule = (
	seed: ModelSeed,
	index: number,
): LlmpricingruletypesLLMPricingRuleDTO => ({
	id: `rule-${seed.modelName}`,
	orgId: ORG_ID,
	enabled: true,
	isOverride: isOverride(index),
	modelName: seed.modelName,
	modelPattern: [`${seed.modelName}*`],
	provider: seed.provider,
	unit: LlmpricingruletypesLLMPricingRuleUnitDTO.per_million_tokens,
	pricing: {
		input: seed.input,
		output: seed.output,
		cache: {
			mode: LlmpricingruletypesLLMPricingRuleCacheModeDTO.subtract,
			read: seed.input / 10,
			write: seed.input * 1.25,
		},
	},
	sourceId: isOverride(index) ? undefined : 'signoz-catalogue',
	syncedAt: isOverride(index) ? null : '2026-08-01T00:00:00Z',
	createdAt: '2026-07-04T09:15:00Z',
	createdBy: 'anna@signoz.io',
	updatedAt: '2026-08-01T00:00:00Z',
	updatedBy: 'anna@signoz.io',
});

export interface PricingRulesQuery {
	offset: number;
	limit: number;
	overridesOnly?: boolean;
}

export const pricingRulesResponse = (
	count: number,
	{ offset, limit, overridesOnly }: PricingRulesQuery,
): ListLLMPricingRules200 => {
	const rules = CATALOGUE.slice(0, count)
		.map(rule)
		.filter((candidate) => !overridesOnly || candidate.isOverride);

	return {
		status: 'success',
		data: {
			items: rules.slice(offset, offset + limit),
			total: rules.length,
			offset,
			limit,
		},
	};
};

const UNPRICED = [
	{ modelName: 'gpt-5-preview', provider: 'openai', spanCount: 18_420 },
	{ modelName: 'claude-opus-5', provider: 'anthropic', spanCount: 6_310 },
	{ modelName: 'deepseek-r2', provider: 'deepseek', spanCount: 940 },
];

export const UNPRICED_MODEL_MAX = UNPRICED.length;

/** Models seen in the last hour of traces that no rule's pattern matches. */
export const unmappedModelsResponse = (
	count: number,
): ListUnmappedLLMModels200 => ({
	status: 'success',
	data: { items: UNPRICED.slice(0, count) },
});

export const RULE_SAVES = ['success', 'loading', 'error'] as const;

export type RuleSave = (typeof RULE_SAVES)[number];

export const RULE_DELETES = ['success', 'loading', 'error'] as const;

export type RuleDelete = (typeof RULE_DELETES)[number];

import type { LlmpricingruletypesUpdatableLLMPricingRulesDTO } from 'api/generated/services/sigNoz.schemas';
import {
	LLM_PRICING_ENDPOINT,
	LLM_UNMAPPED_ENDPOINT,
	makeListResponse,
	makeUnmappedResponse,
	mockRules,
} from 'container/LLMObservability/Settings/ModelPricing/__tests__/fixtures';
import { rest, server } from 'mocks-server/server';
import { render, screen, userEvent, waitFor, within } from 'tests/test-utils';

import UnpricedModelsTab from '../UnpricedModelsTab';

const toastSuccess = jest.fn();
const toastError = jest.fn();
jest.mock('@signozhq/ui/sonner', () => ({
	...jest.requireActual('@signozhq/ui/sonner'),
	toast: {
		success: (...args: unknown[]): void => toastSuccess(...args),
		error: (...args: unknown[]): void => toastError(...args),
	},
}));

const MODEL = 'gpt-4o-mini-2024-07-18';

function setup(): void {
	server.use(
		rest.get(LLM_UNMAPPED_ENDPOINT, (_req, res, ctx) =>
			res(ctx.status(200), ctx.json(makeUnmappedResponse())),
		),
		rest.get(LLM_PRICING_ENDPOINT, (_req, res, ctx) =>
			res(ctx.status(200), ctx.json(makeListResponse(mockRules))),
		),
	);
}

// Picks a billing model in a row's dropdown: open the combobox, then click the
// option. The dropdown fetches its options from the rules list (mocked above).
async function selectRule(
	user: ReturnType<typeof userEvent.setup>,
	modelName: string,
	ruleId: string,
): Promise<void> {
	await user.click(screen.getByTestId(`map-to-select-${modelName}`));
	await user.click(await screen.findByTestId(`map-to-option-${ruleId}`));
}

describe('UnpricedModelsTab (integration)', () => {
	beforeEach(() => {
		window.history.pushState(null, '', '/');
		setup();
	});

	afterEach(() => {
		server.resetHandlers();
		toastSuccess.mockClear();
		toastError.mockClear();
	});

	it('opens the confirm dialog with the target rule pricing when a model is picked', async () => {
		const user = userEvent.setup({ pointerEventsCheck: 0 });
		render(<UnpricedModelsTab />);

		await screen.findByTestId(`unpriced-model-name-${MODEL}`);

		// Picking a rule stages the mapping in the confirm dialog.
		await selectRule(user, MODEL, 'rule-openai');

		const confirmItem = await screen.findByTestId(
			`unpriced-map-confirm-item-${MODEL}`,
		);
		expect(confirmItem).toBeInTheDocument();
		// Shows the target billing model + its pricing so the user can eyeball it.
		expect(screen.getByText('openai:gpt-4o')).toBeInTheDocument();
		expect(screen.getByText('$3.00')).toBeInTheDocument();
		expect(screen.getByText('$9.00')).toBeInTheDocument();
		// While the dialog is open, the row's trigger mirrors the staged pick
		// instead of the placeholder.
		const trigger = screen.getByTestId(`map-to-select-${MODEL}`);
		expect(
			within(trigger).getByText('openai:gpt-4o ($3.00/$9.00)'),
		).toBeInTheDocument();
	});

	it('reverts the row trigger to the placeholder when the mapping is cancelled', async () => {
		const user = userEvent.setup({ pointerEventsCheck: 0 });
		render(<UnpricedModelsTab />);

		await screen.findByTestId(`unpriced-model-name-${MODEL}`);
		await selectRule(user, MODEL, 'rule-openai');

		expect(
			within(screen.getByTestId(`map-to-select-${MODEL}`)).getByText(
				'openai:gpt-4o ($3.00/$9.00)',
			),
		).toBeInTheDocument();

		await user.click(await screen.findByTestId('unpriced-map-cancel-btn'));

		await waitFor(() => {
			const trigger = screen.getByTestId(`map-to-select-${MODEL}`);
			expect(
				within(trigger).getByText('Select / Create a pricing model'),
			).toBeInTheDocument();
		});
	});

	it('commits the mapping in one request when confirmed', async () => {
		const sent: LlmpricingruletypesUpdatableLLMPricingRulesDTO[] = [];
		server.use(
			rest.put(LLM_PRICING_ENDPOINT, async (req, res, ctx) => {
				sent.push(await req.json());
				return res(ctx.status(200), ctx.json({ status: 'success' }));
			}),
		);

		const user = userEvent.setup({ pointerEventsCheck: 0 });
		render(<UnpricedModelsTab />);

		await screen.findByTestId(`unpriced-model-name-${MODEL}`);
		await selectRule(user, MODEL, 'rule-openai');

		await user.click(await screen.findByTestId('unpriced-map-confirm-btn'));

		await waitFor(() => expect(sent).toHaveLength(1));
		expect(sent[0].rules).toHaveLength(1);
		expect(sent[0].rules?.[0].modelPattern).toContain(MODEL);
		await waitFor(() =>
			expect(toastSuccess).toHaveBeenCalledWith('Mapped model'),
		);
		// Dialog closes on success.
		await waitFor(() =>
			expect(
				screen.queryByTestId(`unpriced-map-confirm-item-${MODEL}`),
			).not.toBeInTheDocument(),
		);
	});

	it('cancels the mapping without committing', async () => {
		const sent: LlmpricingruletypesUpdatableLLMPricingRulesDTO[] = [];
		server.use(
			rest.put(LLM_PRICING_ENDPOINT, async (req, res, ctx) => {
				sent.push(await req.json());
				return res(ctx.status(200), ctx.json({ status: 'success' }));
			}),
		);

		const user = userEvent.setup({ pointerEventsCheck: 0 });
		render(<UnpricedModelsTab />);

		await screen.findByTestId(`unpriced-model-name-${MODEL}`);
		await selectRule(user, MODEL, 'rule-openai');

		await user.click(await screen.findByTestId('unpriced-map-cancel-btn'));

		await waitFor(() =>
			expect(
				screen.queryByTestId(`unpriced-map-confirm-item-${MODEL}`),
			).not.toBeInTheDocument(),
		);
		expect(sent).toHaveLength(0);
	});

	it('opens the add-cost drawer prefilled when creating pricing for a model', async () => {
		const user = userEvent.setup({ pointerEventsCheck: 0 });
		render(<UnpricedModelsTab />);

		await screen.findByTestId(`unpriced-model-name-${MODEL}`);

		// Open the row's dropdown and take the "Create a new pricing model" escape hatch
		// instead of mapping onto an existing billing model.
		await user.click(screen.getByTestId(`map-to-select-${MODEL}`));
		await user.click(await screen.findByTestId(`map-to-create-${MODEL}`));

		// The shared add-cost drawer opens with the model name prefilled.
		const drawerTitle = await screen.findByText('Add model cost');
		expect(drawerTitle).toBeInTheDocument();
		expect(screen.getByTestId('drawer-model-id-input')).toHaveValue(MODEL);
	});
});

import { LlmpricingruletypesLLMPricingRuleUnitDTO as UnitDTO } from 'api/generated/services/sigNoz.schemas';
import {
	TOAST_MODEL_COST_DELETED,
	TOAST_MODEL_COST_UPDATED,
} from 'container/LLMObservability/Settings/ModelPricing/constants';
import {
	LLM_PRICING_ENDPOINT,
	LLM_PRICING_RULE_ENDPOINT,
	makeListResponse,
	mockRules,
} from 'container/LLMObservability/Settings/ModelPricing/__tests__/fixtures';
import { rest, server } from 'mocks-server/server';
import { render, screen, userEvent, waitFor, within } from 'tests/test-utils';

import ModelCostTabPanel from '../ModelCostTabPanel';

const toastSuccess = jest.fn();
const toastError = jest.fn();
jest.mock('@signozhq/ui/sonner', () => ({
	...jest.requireActual('@signozhq/ui/sonner'),
	toast: {
		success: (...args: unknown[]): void => toastSuccess(...args),
		error: (...args: unknown[]): void => toastError(...args),
	},
}));

function setupList(items = mockRules, total = items.length): void {
	server.use(
		rest.get(LLM_PRICING_ENDPOINT, (_req, res, ctx) =>
			res(ctx.status(200), ctx.json(makeListResponse(items, total))),
		),
	);
}

function resetUrl(): void {
	window.history.pushState(null, '', '/');
}

async function openRowMenu(
	user: ReturnType<typeof userEvent.setup>,
	ruleId: string,
): Promise<void> {
	const row = screen.getByTestId(`model-cell-name-${ruleId}`).closest('tr');
	await user.click(within(row as HTMLElement).getByRole('button'));
}

describe('ModelCostTabPanel (integration)', () => {
	beforeEach(() => {
		resetUrl();
	});

	afterEach(() => {
		server.resetHandlers();
	});

	it('renders pricing rules returned by the list API', async () => {
		setupList();
		render(<ModelCostTabPanel />);

		const openaiCell = await screen.findByTestId('model-cell-name-rule-openai');
		expect(openaiCell).toHaveTextContent('gpt-4o');
		expect(
			screen.getByTestId('model-cell-name-rule-anthropic'),
		).toHaveTextContent('claude-3-5-sonnet');
		// Canonical id under the model name + provider column.
		expect(screen.getByText('openai:gpt-4o')).toBeInTheDocument();
		expect(screen.getAllByText('OpenAI').length).toBeGreaterThan(0);
		// Source badges reflect the override flag.
		expect(screen.getByTestId('source-badge-rule-openai')).toHaveTextContent(
			'User override',
		);
		expect(screen.getByTestId('source-badge-rule-anthropic')).toHaveTextContent(
			'Auto',
		);
	});

	it('shows the empty state when there are no rules', async () => {
		setupList([], 0);
		render(<ModelCostTabPanel />);

		const empty = await screen.findByTestId('model-costs-empty');
		expect(empty).toHaveTextContent('No model costs yet.');
	});

	it('shows an error message when the list request fails', async () => {
		server.use(
			rest.get(LLM_PRICING_ENDPOINT, (_req, res, ctx) => res(ctx.status(500))),
		);
		render(<ModelCostTabPanel />);

		const alert = await screen.findByRole('alert');
		expect(alert).toHaveTextContent(
			'Failed to load pricing rules. Please try again.',
		);
	});

	it('sends the debounced search term as the q param', async () => {
		const user = userEvent.setup({ pointerEventsCheck: 0 });
		let lastParams: URLSearchParams | null = null;
		server.use(
			rest.get(LLM_PRICING_ENDPOINT, (req, res, ctx) => {
				lastParams = req.url.searchParams;
				return res(ctx.status(200), ctx.json(makeListResponse(mockRules)));
			}),
		);
		render(<ModelCostTabPanel />);

		await screen.findByTestId('model-cell-name-rule-openai');
