			setEditContextMock({
				isEditable: false,
				canEditDashboard: false,
				canDeleteDashboard: false,
				editDisabledTooltip: 'no permission',
				deleteDisabledTooltip: 'no permission',
			});

			renderActions();
			await openActionsMenu();

			await expect(screen.findByText('Rename')).resolves.toBeInTheDocument();
			expect(screen.getByText('New section')).toBeInTheDocument();
			expect(screen.getByText('Delete dashboard')).toBeInTheDocument();
			expect(screen.getByText('Clone dashboard')).toBeInTheDocument();
			// Full screen never depended on permission.
			expect(screen.getByText('Full screen')).toBeInTheDocument();

			expect(screen.getByTestId('dashboard-action-rename')).toHaveAttribute(
				'data-disabled',
			);
			expect(screen.getByTestId('dashboard-action-delete')).toHaveAttribute(
				'data-disabled',
			);
			await waitFor(
				() => {
					expect(screen.getByTestId('dashboard-action-clone')).toHaveAttribute(
						'data-disabled',
					);
				},
				{ timeout: 3000 },
			);
			expect(
				screen.getByTestId('dashboard-action-fullscreen'),
			).not.toHaveAttribute('data-disabled');

			await userEvent.hover(screen.getByTestId('dashboard-action-rename'));
			await expect(screen.findByRole('tooltip')).resolves.toHaveTextContent(
				'no permission',
			);
		});
	});

	describe('partial permissions', () => {
		// Delete is independent of read/update (authz guide rule 3).
		it('enables delete for a user who can only delete', async () => {
			server.use(setupAuthzAllow(buildDashboardDeletePermission(DASHBOARD_ID)));
			setEditContextMock({
				isEditable: false,
				canEditDashboard: false,
				editDisabledTooltip: 'no permission',
			});

			renderActions();

			await waitFor(() => {
				expect(screen.getByTestId('show-drawer')).toHaveAttribute(
					'aria-disabled',
					'true',
				);
			});
			await openActionsMenu();
			await expect(
				screen.findByText('Delete dashboard'),
			).resolves.toBeInTheDocument();
		});

		it('disables clone when create is denied but edit is allowed', async () => {
			server.use(
				setupAuthzAllow(
					buildDashboardReadPermission(DASHBOARD_ID),
					buildDashboardUpdatePermission(DASHBOARD_ID),
					DashboardListPermission,
					IsAdminPermission,
				),
			);
			setEditContextMock({});

			renderActions();

			await waitFor(() => {
				expect(screen.getByTestId('show-drawer')).not.toHaveAttribute(
					'aria-disabled',
					'true',
				);
			});
			await openActionsMenu();
			await expect(
				screen.findByText('Clone dashboard'),
			).resolves.toBeInTheDocument();

			await waitFor(
				() => {
					expect(screen.getByTestId('dashboard-action-clone')).toHaveAttribute(
						'data-disabled',
					);
				},
				{ timeout: 3000 },
			);
			expect(screen.getByTestId('dashboard-action-rename')).not.toHaveAttribute(
				'data-disabled',
			);

			await userEvent.hover(screen.getByTestId('dashboard-action-clone'));
			await expect(screen.findByRole('tooltip')).resolves.toHaveTextContent(
				'is not authorized to perform create',
			);
		});
	});

	describe('permission granted', () => {
		it('enables the toolbar for a full-rights user', async () => {
			server.use(setupAuthzAdmin());
			setEditContextMock({});

			renderActions();

			await waitFor(() => {
				expect(screen.getByTestId('show-drawer')).not.toHaveAttribute(
					'aria-disabled',
					'true',
				);
			});
			expect(screen.getByTestId('add-panel-header')).not.toHaveAttribute(
				'aria-disabled',
				'true',
			);
		});
	});
});

import { render, screen, userEvent } from 'tests/test-utils';

import AuthCard from './AuthCard';

const mockOnCopyInstanceUrl = jest.fn();
const mockOnCreateServiceAccount = jest.fn();

const defaultProps = {
	instanceUrl: 'http://localhost',
	onCopyInstanceUrl: mockOnCopyInstanceUrl,
	onCreateServiceAccount: mockOnCreateServiceAccount,
};

describe('AuthCard', () => {
	afterEach(() => {
		jest.clearAllMocks();
	});

	it('renders the instance URL', () => {
		render(<AuthCard {...defaultProps} isAdmin />);

		expect(screen.getByTestId('mcp-instance-url')).toHaveTextContent(
			'http://localhost',
		);
	});

	it('shows Create Service Account button for admin', () => {
		render(<AuthCard {...defaultProps} isAdmin />);

		expect(screen.getByText('Create service account')).toBeInTheDocument();
		expect(
			screen.queryByText(
				'Only admins can create API keys. Ask your workspace admin for a key with read access, then paste it into the API Key field.',
			),
		).not.toBeInTheDocument();
	});

	it('shows info banner for non-admin', () => {
		render(<AuthCard {...defaultProps} isAdmin={false} />);

		expect(
			screen.getByText(
				'Only admins can create API keys. Ask your workspace admin for a key with read access, then paste it into the API Key field.',
			),
		).toBeInTheDocument();
		expect(screen.queryByText('Create service account')).not.toBeInTheDocument();
	});

	it('calls onCopyInstanceUrl when copy button is clicked', async () => {
		const user = userEvent.setup({ pointerEventsCheck: 0 });

		render(<AuthCard {...defaultProps} isAdmin />);

		await user.click(
			screen.getByRole('button', { name: 'Copy SigNoz instance URL' }),
		);

		expect(mockOnCopyInstanceUrl).toHaveBeenCalledTimes(1);
	});

	it('calls onCreateServiceAccount when admin clicks the CTA', async () => {
		const user = userEvent.setup({ pointerEventsCheck: 0 });

		render(<AuthCard {...defaultProps} isAdmin />);

		await user.click(screen.getByText('Create service account'));

		expect(mockOnCreateServiceAccount).toHaveBeenCalledTimes(1);
	});

	it('shows URL for non-admin (all roles can fetch instance URL)', () => {
		render(<AuthCard {...defaultProps} isAdmin={false} />);

		expect(screen.getByTestId('mcp-instance-url')).toHaveTextContent(
			'http://localhost',
		);
	});

	describe('isLoadingInstanceUrl', () => {
		it('shows a skeleton and hides the URL while loading', () => {
			render(<AuthCard {...defaultProps} isAdmin isLoadingInstanceUrl />);

			expect(screen.queryByTestId('mcp-instance-url')).not.toBeInTheDocument();
			expect(document.querySelector('.ant-skeleton-input')).toBeInTheDocument();
		});

		it('does not render the copy button while loading', () => {
			render(<AuthCard {...defaultProps} isAdmin isLoadingInstanceUrl />);

			expect(
				screen.queryByRole('button', { name: 'Copy SigNoz instance URL' }),
			).not.toBeInTheDocument();
		});

		it('shows the URL and copy button once loading is done', () => {
			render(<AuthCard {...defaultProps} isAdmin isLoadingInstanceUrl={false} />);

			expect(screen.getByTestId('mcp-instance-url')).toHaveTextContent(
				'http://localhost',
			);
			expect(
				screen.getByRole('button', { name: 'Copy SigNoz instance URL' }),
			).toBeInTheDocument();
		});
	});
});

import { Button } from '@signozhq/ui/button';

import { useCanManageAttributeMapping } from '../../hooks/useCanManageAttributeMapping';
import styles from './AttributeMappingActions.module.scss';

interface AttributeMappingActionsProps {
	isDirty: boolean;
	isSaving: boolean;
	onDiscard: () => void;
	onSave: () => void;
}

function AttributeMappingActions({
	isDirty,
	isSaving,
	onDiscard,
	onSave,
}: AttributeMappingActionsProps): JSX.Element | null {
	const canManage = useCanManageAttributeMapping();

	if (!canManage || !isDirty) {
		return null;
	}

	return (
		<div className={styles.actions}>
			<span className={styles.unsavedChanges} data-testid="unsaved-changes">
				Unsaved changes
			</span>
			<Button
				size="md"
				variant="outlined"
				color="secondary"
				onClick={onDiscard}
				disabled={isSaving}
				disabledTooltip="Wait for the save to finish"
				testId="discard-changes-btn"
			>
				Discard
			</Button>
			<Button
				size="md"
				variant="solid"
				color="primary"
				onClick={onSave}
				loading={isSaving}
				testId="save-changes-btn"
			>
				{isSaving ? 'Saving…' : 'Save changes'}
			</Button>
		</div>
	);
}

export default AttributeMappingActions;
